CREATE SCHEMA IF NOT EXISTS fsgg_orchestration;
CREATE TABLE IF NOT EXISTS fsgg_orchestration.pilot_store_metadata(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),schema_version integer NOT NULL,migration_state text NOT NULL CHECK(migration_state IN('applying','ready')),backup_identity uuid NOT NULL,updated_at timestamptz NOT NULL);
DO $guard$ DECLARE rv integer; rs text; ri uuid; BEGIN SELECT schema_version,migration_state,backup_identity INTO rv,rs,ri FROM fsgg_orchestration.store_metadata WHERE singleton; IF NOT FOUND OR rv<>1 OR rs<>'ready' THEN RAISE EXCEPTION 'pilot migration requires ready root schema v1'; END IF; IF EXISTS(SELECT 1 FROM fsgg_orchestration.pilot_store_metadata WHERE singleton AND(schema_version<>1 OR migration_state<>'ready' OR backup_identity<>ri)) THEN RAISE EXCEPTION 'refusing incompatible pilot schema metadata'; END IF; END $guard$;
INSERT INTO fsgg_orchestration.pilot_store_metadata(singleton,schema_version,migration_state,backup_identity,updated_at) SELECT true,1,'ready',backup_identity,statement_timestamp() FROM fsgg_orchestration.store_metadata WHERE singleton ON CONFLICT(singleton) DO NOTHING;
CREATE TABLE IF NOT EXISTS fsgg_orchestration.pilot_stream(permit_id uuid PRIMARY KEY,last_sequence bigint NOT NULL CHECK(last_sequence>=0));
CREATE TABLE IF NOT EXISTS fsgg_orchestration.pilot_event(permit_id uuid NOT NULL REFERENCES fsgg_orchestration.pilot_stream(permit_id),sequence_number bigint NOT NULL CHECK(sequence_number>0),event_id uuid NOT NULL,schema_version integer NOT NULL CHECK(schema_version>0),serializer_version text NOT NULL,payload bytea NOT NULL,payload_sha256 text NOT NULL CHECK(payload_sha256~'^[0-9a-f]{64}$'),recorded_at timestamptz NOT NULL,PRIMARY KEY(permit_id,sequence_number),UNIQUE(permit_id,event_id));
CREATE TABLE IF NOT EXISTS fsgg_orchestration.pilot_inbox(permit_id uuid NOT NULL,command_id uuid NOT NULL,body_sha256 text NOT NULL CHECK(body_sha256~'^[0-9a-f]{64}$'),terminal_sequence bigint NOT NULL CHECK(terminal_sequence>0),received_at timestamptz NOT NULL,PRIMARY KEY(permit_id,command_id),FOREIGN KEY(permit_id,terminal_sequence) REFERENCES fsgg_orchestration.pilot_event(permit_id,sequence_number));
